/* eslint-disable space-in-parens */

import Complex128Array = require( '@stdlib/array/complex128' );
import Complex128 = require( '@stdlib/complex/float64/ctor' );
import zlinspace = require( './index' );


// TESTS //

// The function returns a Complex128Array...
{
	const x = new Complex128Array( 10 );
	const strt = new Complex128( 0.0, 0.0 );
	const stp = new Complex128( 10.0, 5.0 );

	zlinspace( x.length, strt, stp, true, x, 1 ); // $ExpectType Complex128Array
}

// The compiler throws an error if the function is provided a first argument which is not a number...
{
	const x = new Complex128Array( 10 );
	const strt = new Complex128( 0.0, 0.0 );
	const stp = new Complex128( 10.0, 5.0 );

	zlinspace( '10', strt, stp, true, x, 1 ); // $ExpectError
	zlinspace( true, strt, stp, true, x, 1 ); // $ExpectError
	zlinspace( false, strt, stp, true, x, 1 ); // $ExpectError
	zlinspace( null, strt, stp, true, x, 1 ); // $ExpectError
	zlinspace( undefined, strt, stp, true, x, 1 ); // $ExpectError
	zlinspace( [], strt, stp, true, x, 1 ); // $ExpectError
	zlinspace( {}, strt, stp, true, x, 1 ); // $ExpectError
	zlinspace( ( x: number ): number => x, strt, stp, true, x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a complex number...
{
	const x = new Complex128Array( 10 );
	const stp = new Complex128( 10.0, 5.0 );

	zlinspace( x.length, '10', stp, true, x, 1 ); // $ExpectError
	zlinspace( x.length, 10, stp, true, x, 1 ); // $ExpectError
	zlinspace( x.length, true, stp, true, x, 1 ); // $ExpectError
	zlinspace( x.length, false, stp, true, x, 1 ); // $ExpectError
	zlinspace( x.length, null, stp, true, x, 1 ); // $ExpectError
	zlinspace( x.length, undefined, stp, true, x, 1 ); // $ExpectError
	zlinspace( x.length, [], stp, true, x, 1 ); // $ExpectError
	zlinspace( x.length, ( x: number ): number => x, stp, true, x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a complex number...
{
	const x = new Complex128Array( 10 );
	const strt = new Complex128( 0.0, 0.0 );

	zlinspace( x.length, strt,'10', true, x, 1 ); // $ExpectError
	zlinspace( x.length, strt,10, true, x, 1 ); // $ExpectError
	zlinspace( x.length, strt,true, true, x, 1 ); // $ExpectError
	zlinspace( x.length, strt,false, true, x, 1 ); // $ExpectError
	zlinspace( x.length, strt,null, true, x, 1 ); // $ExpectError
	zlinspace( x.length, strt,undefined, true, x, 1 ); // $ExpectError
	zlinspace( x.length, strt,[], true, x, 1 ); // $ExpectError
	zlinspace( x.length, strt,( x: number ): number => x, true, x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a fourth argument which is not a boolean...
{
	const x = new Complex128Array( 10 );
	const strt = new Complex128( 0.0, 0.0 );
	const stp = new Complex128( 10.0, 5.0 );

	zlinspace( x.length, strt, stp, '10', x, 1 ); // $ExpectError
	zlinspace( x.length, strt, stp, 99.99, x, 1 ); // $ExpectError
	zlinspace( x.length, strt, stp, null, x, 1 ); // $ExpectError
	zlinspace( x.length, strt, stp, undefined, x, 1 ); // $ExpectError
	zlinspace( x.length, strt, stp, [], x, 1 ); // $ExpectError
	zlinspace( x.length, strt, stp, {}, x, 1 ); // $ExpectError
	zlinspace( x.length, strt, stp, ( x: number ): number => x, x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a fifth argument which is not a Complex128Array...
{
	const x = new Complex128Array( 10 );
	const strt = new Complex128( 0.0, 0.0 );
	const stp = new Complex128( 10.0, 5.0 );

	zlinspace( x.length, strt, stp, true, 10, 1 ); // $ExpectError
	zlinspace( x.length, strt, stp, true, '10', 1 ); // $ExpectError
	zlinspace( x.length, strt, stp, true, true, 1 ); // $ExpectError
	zlinspace( x.length, strt, stp, true, false, 1 ); // $ExpectError
	zlinspace( x.length, strt, stp, true, null, 1 ); // $ExpectError
	zlinspace( x.length, strt, stp, true, undefined, 1 ); // $ExpectError
	zlinspace( x.length, strt, stp, true, [], 1 ); // $ExpectError
	zlinspace( x.length, strt, stp, true, {}, 1 ); // $ExpectError
	zlinspace( x.length, strt, stp, true, ( x: number ): number => x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a sixth argument which is not a number...
{
	const x = new Complex128Array( 10 );
	const strt = new Complex128( 0.0, 0.0 );
	const stp = new Complex128( 10.0, 5.0 );

	zlinspace( x.length, strt, stp, true, x, '10' ); // $ExpectError
	zlinspace( x.length, strt, stp, true, x, true ); // $ExpectError
	zlinspace( x.length, strt, stp, true, x, false ); // $ExpectError
	zlinspace( x.length, strt, stp, true, x, null ); // $ExpectError
	zlinspace( x.length, strt, stp, true, x, undefined ); // $ExpectError
	zlinspace( x.length, strt, stp, true, x, [] ); // $ExpectError
	zlinspace( x.length, strt, stp, true, x, {} ); // $ExpectError
	zlinspace( x.length, strt, stp, true, x, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = new Complex128Array( 10 );
	const strt = new Complex128( 0.0, 0.0 );
	const stp = new Complex128( 10.0, 5.0 );

	zlinspace(); // $ExpectError
	zlinspace( x.length ); // $ExpectError
	zlinspace( x.length, strt ); // $ExpectError
	zlinspace( x.length, strt, stp ); // $ExpectError
	zlinspace( x.length, strt, stp, true ); // $ExpectError
	zlinspace( x.length, strt, stp, true, x ); // $ExpectError
	zlinspace( x.length, strt, stp, true, x, 1, 10 ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a Complex128Array...
{
	const x = new Complex128Array( 10 );
	const strt = new Complex128( 0.0, 0.0 );
	const stp = new Complex128( 10.0, 5.0 );

	zlinspace.ndarray( x.length, strt, stp, true, x, 1, 0 ); // $ExpectType Complex128Array
}

// The compiler throws an error if the `ndarray` method is provided a first argument which is not a number...
{
	const x = new Complex128Array( 10 );
	const strt = new Complex128( 0.0, 0.0 );
	const stp = new Complex128( 10.0, 5.0 );

	zlinspace.ndarray( '10', strt, stp, true, x, 1, 0 ); // $ExpectError
	zlinspace.ndarray( true, strt, stp, true, x, 1, 0 ); // $ExpectError
	zlinspace.ndarray( false, strt, stp, true, x, 1, 0 ); // $ExpectError
	zlinspace.ndarray( null, strt, stp, true, x, 1, 0 ); // $ExpectError
	zlinspace.ndarray( undefined, strt, stp, true, x, 1, 0 ); // $ExpectError
	zlinspace.ndarray( [], strt, stp, true, x, 1, 0 ); // $ExpectError
	zlinspace.ndarray( {}, strt, stp, true, x, 1, 0 ); // $ExpectError
	zlinspace.ndarray( ( x: number ): number => x, strt, stp, true, x, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a second argument which is not a complex number...
{
	const x = new Complex128Array( 10 );
	const stp = new Complex128( 10.0, 5.0 );

	zlinspace.ndarray( x.length, '10', stp, true, x, 1, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, 10, stp, true, x, 1, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, true, stp, true, x, 1, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, false, stp, true, x, 1, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, null, stp, true, x, 1, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, undefined, stp, true, x, 1, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, [], stp, true, x, 1, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, ( x: number ): number => x, stp, true, x, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a third argument which is not a complex number...
{
	const x = new Complex128Array( 10 );
	const strt = new Complex128( 0.0, 0.0 );

	zlinspace.ndarray( x.length, strt,'10', true, x, 1, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, strt,10, true, x, 1, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, strt,true, true, x, 1, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, strt,false, true, x, 1, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, strt,null, true, x, 1, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, strt,undefined, true, x, 1, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, strt,[], true, x, 1, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, strt,( x: number ): number => x, true, x, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fourth argument which is not a boolean...
{
	const x = new Complex128Array( 10 );
	const strt = new Complex128( 0.0, 0.0 );
	const stp = new Complex128( 10.0, 5.0 );

	zlinspace.ndarray( x.length, strt, stp, '10', x, 1, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp, 99.99, x, 1, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp, null, x, 1, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp, undefined, x, 1, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp, [], x, 1, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp, {}, x, 1, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp, ( x: number ): number => x, x, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fifth argument which is not a Complex128Array...
{
	const x = new Complex128Array( 10 );
	const strt = new Complex128( 0.0, 0.0 );
	const stp = new Complex128( 10.0, 5.0 );

	zlinspace.ndarray( x.length, strt, stp, true, 10, 1, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp, true, '10', 1, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp, true, true, 1, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp, true, false, 1, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp, true, null, 1, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp, true, undefined, 1, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp, true, [], 1, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp, true, {}, 1, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp, true, ( x: number ): number => x, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a sixth argument which is not a number...
{
	const x = new Complex128Array( 10 );
	const strt = new Complex128( 0.0, 0.0 );
	const stp = new Complex128( 10.0, 5.0 );

	zlinspace.ndarray( x.length, strt, stp, true, x, '10', 0 ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp, true, x, true, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp, true, x, false, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp, true, x, null, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp, true, x, undefined, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp, true, x, [], 0 ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp, true, x, {}, 0 ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp, true, x, ( x: number ): number => x, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a seventh argument which is not a number...
{
	const x = new Complex128Array( 10 );
	const strt = new Complex128( 0.0, 0.0 );
	const stp = new Complex128( 10.0, 5.0 );

	zlinspace.ndarray( x.length, strt, stp, true, x, 1, '10' ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp, true, x, 1, true ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp, true, x, 1, false ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp, true, x, 1, null ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp, true, x, 1, undefined ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp, true, x, 1, [] ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp, true, x, 1, {} ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp, true, x, 1, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	const x = new Complex128Array( 10 );
	const strt = new Complex128( 0.0, 0.0 );
	const stp = new Complex128( 10.0, 5.0 );

	zlinspace.ndarray(); // $ExpectError
	zlinspace.ndarray( x.length ); // $ExpectError
	zlinspace.ndarray( x.length, strt ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp, true ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp, true, x ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp, true, x, 1 ); // $ExpectError
	zlinspace.ndarray( x.length, strt, stp, true, x, 1, 0, 10 ); // $ExpectError
}
